-- stg_mc_plants_destroyed: part 1 of 1, 7544 rows. NOT APPLIED, branch only.
-- Licence on every row comes from the FILE, never the filename.
create table if not exists public.stg_mc_plants_destroyed (
  col text,
  col_2 text,
  plant text,
  col_3 text,
  col_4 text,
  plant_batch text,
  tag_type text,
  strain text,
  col_5 text,
  location text,
  location_type text,
  sublocation text,
  hold text,
  plant_batch_date text,
  phase text,
  phase_date text,
  phase_length text,
  harvested text,
  source_file text not null,
  file_sha256 text not null,
  licence text not null,
  file_window text,
  ingested_at timestamptz not null default now()
);
alter table public.stg_mc_plants_destroyed enable row level security;
drop policy if exists stg_mc_plants_destroyed_read on public.stg_mc_plants_destroyed;
create policy stg_mc_plants_destroyed_read on public.stg_mc_plants_destroyed for select to authenticated using (true);
